import sys
def isMatch(s, p):
    sn, pn = len(s), len(p); si = pi = 0; star = -1; s_ptr = -1
    while si < sn:
        if pi < pn and (p[pi] == '?' or p[pi] == s[si]): si += 1; pi += 1
        elif pi < pn and p[pi] == '*': star = pi; s_ptr = si; pi += 1
        elif star != -1: pi = star + 1; s_ptr += 1; si = s_ptr
        else: return False
    while pi < pn and p[pi] == '*': pi += 1
    return pi == pn
if __name__ == '__main__':
    lines = sys.stdin.read().strip().split()
    if len(lines) >= 2: print(str(isMatch(lines[0].strip('"'), lines[1].strip('"'))).lower())
